                {"question": "Why is depreciation added back when calculating free cash flow?", "options": ["It was double-counted as an error", "It reduced EBIT but is not an actual cash outflow", "It represents a tax refund", "Depreciation should never be added back"], "correct_index": 1, "explanation": "Depreciation lowers accounting profit without using cash, so it is added back to reach a cash-based figure."},
                {"question": "What does subtracting the increase in net working capital account for?", "options": ["Cash tied up funding day-to-day operations like receivables and inventory", "The company's tax liability", "Dividend payments", "Depreciation expense"], "correct_index": 0, "explanation": "A rise in working capital means cash is tied up in operations (e.g. receivables), reducing free cash flow."},
                {"question": "Why is unlevered free cash flow calculated before interest expense on debt?", "options": ["Interest does not exist in real companies", "It represents cash available to all capital providers, debt and equity, before financing decisions", "It is a mistake commonly made by analysts", "Only levered companies calculate free cash flow"], "correct_index": 1, "explanation": "Unlevered FCF is capital-structure-neutral, representing cash generated for all investors before financing splits."}
